"""Render Settings into an ai-marketplace-monitor config.toml.

Serialisation goes through tomli_w, so user-supplied strings can never break
out of their TOML value into new sections or keys.
"""

from __future__ import annotations

from typing import Any
from urllib.parse import urlparse

import tomli_w

from deal_hunter import profile
from deal_hunter.settings import NOTIFIERS, Settings, WatchSettings, quote_phrase

USER = "me"
MARKETPLACE = "facebook"

_AI_KEY_ENV = {"anthropic": "ANTHROPIC_API_KEY", "openai": "OPENAI_API_KEY"}

HEADER = """\
# Generated by deal-hunter from deal-hunter.toml — edits here are overwritten.
# Secrets are ${ENV_VAR} placeholders expanded by ai-marketplace-monitor.

"""


_AI_HOSTS = {"anthropic": "api.anthropic.com", "openai": "api.openai.com"}


def secret_destinations(settings: Settings) -> list[str]:
    """The settings-chosen hosts that receive a key or token, for `run` to show.

    A settings file is all it takes to send the API key elsewhere (ai.base_url),
    so a run from a planted or mistaken file should say where things go.
    """
    hosts = []
    ai = settings.ai
    if ai.base_url:
        hosts.append(f"AI key -> {urlparse(ai.base_url).hostname}")
    elif ai.provider in _AI_HOSTS:
        hosts.append(f"AI key -> {_AI_HOSTS[ai.provider]}")
    fields = settings.notify.fields
    if "ntfy_server" in fields:
        hosts.append(f"ntfy topic -> {urlparse(str(fields['ntfy_server'])).hostname}")
    if "email" in fields:
        domain = str(fields["email"]).rsplit("@", 1)[-1]
        hosts.append(f"SMTP password -> {fields.get('smtp_server', f'smtp.{domain}')}")
    return hosts


def required_env(settings: Settings) -> list[str]:
    """Environment variables the rendered config references."""
    names: list[str] = []
    if settings.ai.provider in _AI_KEY_ENV:
        names.append(_AI_KEY_ENV[settings.ai.provider])
    for method in settings.notify.methods:
        names.extend(NOTIFIERS[method].values())
    return names


def build_config(settings: Settings) -> dict[str, Any]:
    loc, search, ai = settings.location, settings.search, settings.ai

    marketplace: dict[str, Any] = {
        "search_city": loc.search_city,
        "radius": loc.radius,
        "search_interval": search.interval,
        "max_search_interval": search.max_interval,
        "availability": "in",
        # Local only: Facebook's own pickup filter, backed by shipping
        # antikeywords and the AI prompt for mis-tagged listings.
        "delivery_method": "local_pick_up",
        # Wide net on the first pass, then only fresh listings.
        "date_listed": ["last 7 days", "last 24 hours"],
    }
    if loc.seller_locations:
        marketplace["seller_locations"] = loc.seller_locations
    if settings.anonymous:
        marketplace["login_wait_time"] = 0
    marketplace["notify"] = USER

    items = {watch.name: build_item(watch, settings) for watch in settings.watches}

    config: dict[str, Any] = {
        "marketplace": {MARKETPLACE: marketplace},
        "item": items,
    }

    if ai.provider != "none":
        section: dict[str, Any] = {"provider": ai.provider}
        if ai.provider in _AI_KEY_ENV:
            section["api_key"] = f"${{{_AI_KEY_ENV[ai.provider]}}}"
        if ai.model:
            section["model"] = ai.model
        if ai.base_url:
            section["base_url"] = ai.base_url
        if ai.provider == "ollama":
            section["timeout"] = 120
        config["ai"] = {ai.provider: section}

    # aimm requires a user section even when notifying console-only. Credentials
    # are inlined on the user, so aimm uses every method configured here.
    user: dict[str, Any] = {"with_description": 200}
    for method in settings.notify.methods:
        for field_name, env in NOTIFIERS[method].items():
            user[field_name] = f"${{{env}}}"
    user.update(settings.notify.fields)
    config["user"] = {USER: user}

    return config


def build_item(watch: WatchSettings, settings: Settings) -> dict[str, Any]:
    """One watch as an aimm [item.*] table."""
    preset = profile.PRESETS[watch.preset] if watch.preset else None
    antikeywords = list(preset.antikeywords if preset else profile.COMMON_ANTIKEYWORDS)
    if preset is not None:
        if not watch.allow_barebones:
            antikeywords += preset.barebones_antikeywords
    antikeywords += [quote_phrase(k) for k in watch.antikeywords]

    item: dict[str, Any] = {"search_phrases": watch.search_phrases}
    if watch.keywords:
        item["keywords"] = watch.keywords
    item |= {
        "min_price": watch.min_price,
        "max_price": watch.max_price,
        "antikeywords": antikeywords,
        "prompt": preset.prompt if preset else profile.GENERIC_PROMPT,
        "rating_prompt": preset.rating_prompt if preset else profile.GENERIC_RATING_PROMPT,
        "rating": watch.rating,
    }
    if watch.preferences:
        item["description"] = watch.preferences
    if settings.ai.provider == "none":
        item["ai"] = []
    return item


def render(settings: Settings) -> str:
    return HEADER + tomli_w.dumps(build_config(settings), multiline_strings=True)
